test('overdueInvoices', async (t) => {
  await t.test('returns empty array when no invoices', () => {
    const result = overdueInvoices([], '2026-10-07');
    assert.deepStrictEqual(result, []);
  });

  await t.test('filters out draft invoices', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-09-01', status: 'draft', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 0);
  });

  await t.test('filters out paid invoices', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-09-01', status: 'paid', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 0);
  });

  await t.test('filters out invoices with future due dates', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-10-15', status: 'issued', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 0);
  });

  await t.test('includes issued invoices with past due dates', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-09-01', status: 'issued', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].number, 'INV-1');
  });

  await t.test('includes partially_paid invoices with past due dates', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-09-01', status: 'partially_paid', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].number, 'INV-1');
  });

  await t.test('sorts by most overdue first (highest daysOverdue)', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-08-01', status: 'issued', lines: [] },
      { number: 'INV-2', customerId: 'CUST2', dueDate: '2026-09-15', status: 'issued', lines: [] },
      { number: 'INV-3', customerId: 'CUST3', dueDate: '2026-09-01', status: 'issued', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 3);
    assert.strictEqual(result[0].number, 'INV-1'); // 67 days overdue
    assert.strictEqual(result[1].number, 'INV-3'); // 36 days overdue
    assert.strictEqual(result[2].number, 'INV-2'); // 22 days overdue
  });

  await t.test('calculates daysOverdue correctly', () => {
    const invoices = [
      { number: 'INV-1', customerId: 'CUST1', dueDate: '2026-10-05', status: 'issued', lines: [] },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result[0].daysOverdue, 2);
  });

  await t.test('includes due amount for fully unpaid issued invoice', () => {
    const invoices = [
      {
        number: 'INV-1',
        customerId: 'CUST1',
        dueDate: '2026-09-01',
        status: 'issued',
        lines: [{ qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result[0].due, 50000);
  });

  await t.test('includes remaining due amount for partially_paid invoice', () => {
    const invoices = [
      {
        number: 'INV-1',
        customerId: 'CUST1',
        dueDate: '2026-09-01',
        status: 'partially_paid',
        lines: [{ qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
        payments: [{ amount: 20000, date: '2026-09-15' }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result[0].due, 30000);
  });

  await t.test('returns correct shape with all required fields', () => {
    const invoices = [
      {
        number: 'INV-42',
        customerId: 'MYCUST',
        dueDate: '2026-09-01',
        status: 'issued',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    const inv = result[0];
    assert.strictEqual(inv.number, 'INV-42');
    assert.strictEqual(inv.customerId, 'MYCUST');
    assert.strictEqual(inv.dueDate, '2026-09-01');
    assert.strictEqual(typeof inv.daysOverdue, 'number');
    assert.strictEqual(typeof inv.due, 'number');
  });

  await t.test('handles invoices with discounts and VAT', () => {
    const invoices = [
      {
        number: 'INV-1',
        customerId: 'CUST1',
        dueDate: '2026-09-01',
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 20 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-07');
    assert.strictEqual(result.length, 1);
    const due = result[0].due;
    assert.strictEqual(typeof due, 'number');
    assert(due > 0);
  });
});

test('vatSummary', async (t) => {
  await t.test('returns empty array when no invoices', () => {
    const result = vatSummary([]);
    assert.deepStrictEqual(result, []);
  });

  await t.test('filters out draft invoices', () => {
    const invoices = [
      { status: 'draft', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 0);
  });

  await t.test('includes issued invoices', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
  });

  await t.test('includes partially_paid invoices', () => {
    const invoices = [
      { status: 'partially_paid', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
  });

  await t.test('includes paid invoices', () => {
    const invoices = [
      { status: 'paid', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
  });

  await t.test('aggregates multiple lines with same VAT rate', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 200, unitPrice: 500, discountPercent: 0, vatRate: 20 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[0].base, 200000); // 100*1000 + 200*500
    assert.strictEqual(result[0].vat, 40000); // 200000 * 20 / 100
  });

  await t.test('aggregates multiple invoices with same VAT rate', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[0].base, 200000);
    assert.strictEqual(result[0].vat, 40000);
  });

  await t.test('separates different VAT rates', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 10 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 2);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[1].rate, 10);
  });

  await t.test('sorts by rate descending (high to low)', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 10 },
          { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 5 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 3);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[1].rate, 10);
    assert.strictEqual(result[2].rate, 5);
  });

  await t.test('calculates base correctly (after discount)', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 90000); // 100*1000 - 10% discount = 90000
    assert.strictEqual(result[0].vat, 18000); // 90000 * 20 / 100 = 18000
  });

  await t.test('handles zero VAT rate', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 0);
    assert.strictEqual(result[0].base, 100000);
    assert.strictEqual(result[0].vat, 0);
  });

  await t.test('handles missing vatRate (defaults to 0)', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 0);
  });

  await t.test('handles missing discountPercent (defaults to 0)', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, vatRate: 20 }] },
